871	/* ──────────────────────────────────────────────────────────
872	   REDUCED MOTION — disable transforms, keep opacity fades
873	────────────────────────────────────────────────────────── */
874	@media (prefers-reduced-motion: reduce) {
875	  *,
876	  *::before,
877	  *::after {
878	    animation-duration: 0.01ms !important;
879	    animation-iteration-count: 1 !important;
880	    transition-duration: 0.01ms !important;
881	    scroll-behavior: auto !important;
882	  }
883	
884	  /* Allow opacity-only fades at full duration — these are safe */
885	  .motion-safe-fade {
886	    animation-duration: var(--duration-base) !important;
887	    transition-duration: var(--duration-base) !important;
888	  }
889	}
